"""Offline test for apple-app/scripts/apply-android-config.py on Capacitor 8's stock Android files."""
import importlib.util
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("apply_android", ROOT / "apple-app" / "scripts" / "apply-android-config.py")
aa = importlib.util.module_from_spec(spec)
spec.loader.exec_module(aa)

fails = []
def check(name, ok, detail=""):
    print(("  [PASS] " if ok else "  [FAIL] ") + name + (f"  {detail}" if detail else ""))
    if not ok:
        fails.append(name)

# As generated by `npx cap add android` (Capacitor 8 template).
GRADLE = """apply plugin: 'com.android.application'

android {
    namespace = "ch.snowmapper.app"
    compileSdk = rootProject.ext.compileSdkVersion
    defaultConfig {
        applicationId "ch.snowmapper.app"
        minSdkVersion rootProject.ext.minSdkVersion
        targetSdkVersion rootProject.ext.targetSdkVersion
        versionCode 1
        versionName "1.0"
        testInstrumentationRunner "androidx.test.runner.AndroidJUnitRunner"
    }
    buildTypes {
        release {
            minifyEnabled false
            proguardFiles getDefaultProguardFile('proguard-android.txt'), 'proguard-rules.pro'
        }
    }
}
"""

MANIFEST = """<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">

    <application
        android:allowBackup="true"
        android:theme="@style/AppTheme">

        <activity
            android:configChanges="orientation|keyboardHidden|keyboard|screenSize|locale|smallestScreenSize|screenLayout|uiMode|navigation|density"
            android:name=".MainActivity"
            android:label="@string/title_activity_main"
            android:launchMode="singleTask"
            android:exported="true">
        </activity>
    </application>

    <!-- Permissions -->

    <uses-permission android:name="android.permission.INTERNET" />
</manifest>
"""

print("build.gradle")
g, ch = aa.patch_gradle(GRADLE, "1.2.0", "42")
check("versionCode set", "versionCode 42" in g and "versionCode 1\n" not in g)
check("versionName set", 'versionName "1.2.0"' in g)
check("signingConfigs block added once", g.count("signingConfigs {") == 1)
rel = g.split("buildTypes {", 1)[1]
check("release uses the signing config only when the env var is set",
      "if (System.getenv('ANDROID_KEYSTORE_FILE'))" in rel and "signingConfig signingConfigs.release" in rel)
check("signingConfigs declared before buildTypes", g.index("signingConfigs {") < g.index("buildTypes {"))
check("no secret values in the file", "storePassword System.getenv('ANDROID_KEYSTORE_PASSWORD')" in g)
check("braces balanced", g.count("{") == g.count("}"))
g2, ch2 = aa.patch_gradle(g, "1.2.0", "42")
check("idempotent", g2 == g and ch2 == [], str(ch2))
g3, _ = aa.patch_gradle(g, "1.2.1", "43")
check("re-run bumps the version", "versionCode 43" in g3 and 'versionName "1.2.1"' in g3 and g3.count("signingConfigs {") == 1)

print("AndroidManifest.xml")
m, ch = aa.patch_manifest(MANIFEST)
check("fine location", 'android.permission.ACCESS_FINE_LOCATION' in m)
check("coarse location", 'android.permission.ACCESS_COARSE_LOCATION' in m)
check("no camera / media permission", "CAMERA" not in m and "READ_MEDIA" not in m)
check("portrait on MainActivity", 'android:name=".MainActivity"\n            android:screenOrientation="portrait"' in m)
check("still ends with </manifest>", m.rstrip().endswith("</manifest>"))
m2, ch2 = aa.patch_manifest(m)
check("idempotent", m2 == m and ch2 == [], str(ch2))

if fails:
    print(f"\n{len(fails)} FAILED")
    sys.exit(1)
print("\nall passed")
